import React from 'react';
import { useNavigate } from 'react-router-dom';
import './MainPage.css'; // Ensure you have this CSS file for styling

const MainPage = () => {
  const navigate = useNavigate();

  const navigateToProfile = () => {
    navigate('/profile'); // Navigate to the profile page
  };

  const navigateToChat = () => {
    navigate('/chat'); // Navigate to the chat page
  };

  return (
    <div className="main-container">
      {/* Top Navigation Bar */}
      <div className="top-nav">
        <img src="/images/image1.png" alt="Logo" className="logo" /> {/* Replace with your image */}
        <div className="search-bar">
          <input type="text" placeholder="Search..." />
        </div>
        <div className="nav-links">
          <span onClick={navigateToProfile} className="profile-link">Profile</span>
          <span onClick={navigateToChat} className="chat-link">Chat</span>
          <img src="user.png" alt="User" className="user-image" /> {/* Replace with your user image */}
        </div>
      </div>

      {/* Cards Section */}
      <div className="cards-container">
        {/* Example Card */}
        <div className="card">
          <h3 className="poster-name">John Doe</h3>
          <p className="field">Marketing</p>
          <p className="description">Looking for a marketing expert to help with a new campaign.</p>
          <p className="money-offered">$500</p>
          <div className="offer-section">
            <input type="text" placeholder="Enter your offer..." />
            <textarea placeholder="Write a message to the poster..."></textarea>
          </div>
          <button className="post-button">Post Offer</button>
        </div>

        {/* Add more cards dynamically here */}
      </div>
    </div>
  );
};

export default MainPage;
